/*Table structure for table `parametro` */

DROP TABLE IF EXISTS `parametro`;

CREATE TABLE `parametro` (
  `id_parametro` int(11) NOT NULL AUTO_INCREMENT,
  `nombre` varchar(100) NOT NULL,
  `tipo` varchar(30) NOT NULL,
  `valor` text NOT NULL,
  `fecha_alta` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `fecha_modif` datetime(3) NOT NULL,
  `grupo_parametros` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`id_parametro`),
  UNIQUE KEY `parametro_nombre_key` (`nombre`),
  KEY `parametro_grupo_parametros_idx` (`grupo_parametros`)
) ENGINE=InnoDB AUTO_INCREMENT=34 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

/*Data for the table `parametro` */


/*Table structure for table `precio_producto` */

DROP TABLE IF EXISTS `precio_producto`;

CREATE TABLE `precio_producto` (
  `id_producto` int(11) NOT NULL,
  `fecha_desde` date NOT NULL,
  `precio` decimal(12,2) NOT NULL,
  PRIMARY KEY (`id_producto`,`fecha_desde`),
  CONSTRAINT `precio_producto_id_producto_fkey` FOREIGN KEY (`id_producto`) REFERENCES `producto` (`id_producto`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

/*Data for the table `precio_producto` */


/*Table structure for table `producto` */

DROP TABLE IF EXISTS `producto`;

CREATE TABLE `producto` (
  `id_producto` int(11) NOT NULL AUTO_INCREMENT,
  `titulo` varchar(255) NOT NULL,
  `slug` varchar(255) NOT NULL,
  `descripcion` text NOT NULL,
  `sku` varchar(100) DEFAULT NULL,
  `odoo_id` int(11) DEFAULT NULL,
  `id_marca` int(11) DEFAULT NULL,
  `cuotas_max` int(11) DEFAULT NULL,
  `activo` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id_producto`),
  UNIQUE KEY `producto_slug_key` (`slug`),
  UNIQUE KEY `producto_odoo_id_key` (`odoo_id`),
  KEY `producto_id_marca_fkey` (`id_marca`),
  CONSTRAINT `producto_id_marca_fkey` FOREIGN KEY (`id_marca`) REFERENCES `marca` (`id_marca`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=780 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

